sys_script.script:
(function executeRule(current, previous) {

    // End Date is optional.
    // If End Date is empty, there is nothing to validate.
    if (current.getValue('end_date') == '') {
        return;
    }

    // Start Date is required for End Date comparison.
    if (current.getValue('start_date') == '') {
        gs.addErrorMessage(
            'Start Date must be entered before specifying an End Date.'
        );

        current.setAbortAction(true);
        return;
    }

    // Get the date values in YYYY-MM-DD format.
    var startDate = current.getValue('start_date');
    var endDate = current.getValue('end_date');

    // End Date cannot be before Start Date.
    if (endDate < startDate) {

        gs.addErrorMessage(
            'End Date cannot be before Start Date. Please enter an End Date equal to or later than the Start Date.'
        );

        current.setAbortAction(true);
        return;
    }

})(current, previous);
